#!/usr/bin/env bash
# Complete recode of the Kiosk Process status system.
#
# WHY: every earlier fix in this series was patching a single symptom of
# the same root problem — the Admin Panel had no real signal for when the
# Agent actually STARTED executing a command, only when it was queued and
# when it finished. Everything in between (the status pill, the progress
# bar) was guessing from a single click timestamp. This recode removes the
# guessing:
#
#   - New InstanceCommand.started_at column + a real
#     POST .../commands/<id>/start endpoint, called by the Agent the
#     instant it picks a command off the queue, BEFORE executing it.
#     ack_command now accepts the pending -> in_progress -> success/failed
#     transition (previously only pending -> success/failed).
#   - The Kiosk Process panel's "what's in flight" query is now scoped to
#     start/stop/restart/configure only. Previously ANY pending
#     InstanceCommand (including an unrelated "Run a command on this
#     kiosk" one-off shell command) would hijack the status pill into a
#     generic "Working…" state — a real bug, now fixed.
#   - The status pill + progress UI now show two honestly-labeled phases
#     instead of one guessed percentage:
#       "pending"     — queued, Agent hasn't confirmed pickup yet.
#                       Genuinely unbounded (Agent long-polls up to 20s at
#                       a time, or could be offline) — shown as an
#                       indeterminate sweep + real elapsed-seconds count,
#                       not a fake percentage.
#       "in_progress" — Agent has confirmed it's actually executing this.
#                       Only here do we show a determinate % bar, and it's
#                       anchored to the real started_at instead of the
#                       click time, so estimates only need to cover the
#                       command's own execution (e.g. stop's up-to-10s
#                       graceful-shutdown grace period), not the unknown
#                       queue-to-pickup delay too.
#
# Files touched: app/models.py, app/blueprints/agent_api.py,
# app/blueprints/instances.py, app/templates/instances/detail.html,
# agent/api_client.py, agent/commands.py, a new Alembic migration, and a
# rebuilt app/static/installers/opslab-agent.tar.gz (for future installs).
#
# IMPORTANT: as with the previous heartbeat-timing fix, the agent/ changes
# only take effect on machines running the updated Agent. There is still
# no remote Agent self-update channel — already-enrolled kiosks need the
# Agent reinstalled (re-run install.sh/install.ps1) to get the
# start_command signal. Until then they'll keep working exactly as before
# this recode (falling back to the old click-time guess), not break.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app agent migrations requirements.txt run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS"
cp app/models.py "backups/$TS/models.py.bak" 2>/dev/null || true
cp app/blueprints/agent_api.py "backups/$TS/agent_api.py.bak" 2>/dev/null || true
cp app/blueprints/instances.py "backups/$TS/instances.py.bak" 2>/dev/null || true
cp app/templates/instances/detail.html "backups/$TS/detail.html.bak" 2>/dev/null || true
cp agent/api_client.py "backups/$TS/api_client.py.bak" 2>/dev/null || true
cp agent/commands.py "backups/$TS/commands.py.bak" 2>/dev/null || true
cp app/static/installers/opslab-agent.tar.gz "backups/$TS/opslab-agent.tar.gz.bak" 2>/dev/null || true
cp -r admin_panel.db "backups/$TS/admin_panel.db.bak" 2>/dev/null || true
echo "==> Backed up existing files (incl. a DB copy, since this push includes a migration) to backups/$TS/"

echo "==> Writing app/models.py"
base64 -d > app/models.py << 'MODELS_PY_B64'

MODELS_PY_B64

echo "==> Writing app/blueprints/agent_api.py"
base64 -d > app/blueprints/agent_api.py << 'AGENT_API_PY_B64'

AGENT_API_PY_B64

echo "==> Writing app/blueprints/instances.py"
base64 -d > app/blueprints/instances.py << 'INSTANCES_PY_B64'

INSTANCES_PY_B64

echo "==> Writing app/templates/instances/detail.html"
base64 -d > app/templates/instances/detail.html << 'DETAIL_HTML_B64'

DETAIL_HTML_B64

echo "==> Writing agent/api_client.py"
base64 -d > agent/api_client.py << 'API_CLIENT_PY_B64'

API_CLIENT_PY_B64

echo "==> Writing agent/commands.py"
base64 -d > agent/commands.py << 'COMMANDS_PY_B64'

COMMANDS_PY_B64

echo "==> Writing new Alembic migration (instance_commands.started_at)"
base64 -d > migrations/versions/9a1f2c7d4e6b_add_instance_commands_started_at.py << 'MIGRATION_PY_B64'

MIGRATION_PY_B64

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (for future installs)"
base64 -d > app/static/installers/opslab-agent.tar.gz << 'AGENT_TAR_B64'

AGENT_TAR_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/models.py').read())"
python3 -c "import ast; ast.parse(open('app/blueprints/agent_api.py').read())"
python3 -c "import ast; ast.parse(open('app/blueprints/instances.py').read())"
python3 -c "import ast; ast.parse(open('agent/api_client.py').read())"
python3 -c "import ast; ast.parse(open('agent/commands.py').read())"
python3 -c "import ast; ast.parse(open('migrations/versions/9a1f2c7d4e6b_add_instance_commands_started_at.py').read())"
echo "    all Python files: syntax OK"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null
echo "    served agent tarball is readable"

echo ""
echo "==> Applying database migration (adds instance_commands.started_at)"
source venv/bin/activate
FLASK_APP=run.py python -m flask db upgrade

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Kiosk Process status system recoded. Two real phases now, not one"
echo "guess:"
echo "  - 'Queued' (indeterminate sweep + elapsed seconds) while waiting"
echo "    for the Agent to pick the command up."
echo "  - 'Starting/Stopping/Restarting/Configuring…' (real % bar) once"
echo "    the Agent has actually confirmed it started executing."
echo "  - 'Run a command on this kiosk' no longer hijacks this panel's"
echo "    status pill."
echo ""
echo "IMPORTANT - as before, already-enrolled kiosks need the Agent"
echo "reinstalled (re-run install.sh/install.ps1) to send the new"
echo "start_command signal. Until then they'll behave exactly like before"
echo "this recode - not broken, just back to the old click-time guess for"
echo "the 'in_progress' phase specifically."
echo "==================================================================="
